    <!-- Generator Control Toolbar -->\n    <div class=\"mt-6 p-4 rounded-xl border border-[#1e2333] hover:border-[#10b981]/50 bg-black/5 dark:bg-white/5 flex flex-wrap items-center justify-between gap-4\">\n      <div class=\"flex items-center flex-wrap gap-3\">\n        <span class=\"text-xs font-mono opacity-70\">Anzahl:</span>\n        <div class=\"flex items-center gap-1\">\n          <button class=\"btn-qty px-2.5 py-1 text-xs rounded border border-[#1e2333] hover:border-[#10b981]/50 font-mono font-bold bg-white/15\" data-val=\"1\">1</button>\n          <button class=\"btn-qty px-2.5 py-1 text-xs rounded border border-[#1e2333] hover:border-[#10b981]/50 font-mono hover:bg-white/10\" data-val=\"5\">5</button>\n          <button class=\"btn-qty px-2.5 py-1 text-xs rounded border border-[#1e2333] hover:border-[#10b981]/50 font-mono hover:bg-white/10\" data-val=\"10\">10</button>\n          <button class=\"btn-qty px-2.5 py-1 text-xs rounded border border-[#1e2333] hover:border-[#10b981]/50 font-mono hover:bg-white/10\" data-val=\"25\">25</button>\n        </div>\n\n        <div class=\"flex items-center gap-3 text-xs font-mono ml-2\">\n          <label class=\"flex items-center space-x-1.5 cursor-pointer opacity-80 hover:opacity-100\">\n            <input type=\"checkbox\" id=\"chk-hyphens\" checked class=\"rounded accent-emerald-500\">\n            <span>Mit Bindestrich</span>\n          </label>\n          <label class=\"flex items-center space-x-1.5 cursor-pointer opacity-80 hover:opacity-100\">\n            <input type=\"checkbox\" id=\"chk-upper\" class=\"rounded accent-emerald-500\">\n            <span>Großbuchstaben</span>\n          </label>\n          <label class=\"flex items-center space-x-1.5 cursor-pointer opacity-80 hover:opacity-100\">\n            <input type=\"checkbox\" id=\"chk-braces\" class=\"rounded accent-emerald-500\">\n            <span>{ Klammern }</span>\n          </label>\n        </div>\n      </div>\n\n      <div class=\"flex items-center gap-2\">\n        <button id=\"btn-generate\" class=\"px-5 py-2 rounded-xl font-bold transition flex items-center space-x-2 text-xs bg-[#10b981] hover:bg-[#059669] text-black font-bold tracking-tight shadow-[0_0_15px_rgba(16,185,129,0.3)]\">\n          <span>Generieren</span>\n        </button>\n      </div>\n    </div>\n\n    <!-- UUID Output Cards List -->\n    <div class=\"mt-4\">\n      <div class=\"flex items-center justify-between mb-2\">\n        <span class=\"text-xs font-bold uppercase tracking-wider font-mono opacity-80\">Generierte Bezeichner</span>\n        <button id=\"btn-copy-all\" class=\"text-xs font-mono font-bold hover:underline opacity-80 hover:opacity-100\" style=\"color: #10b981\">Alle Kopieren</button>\n      </div>\n      <div id=\"uuid-list\" class=\"space-y-2 max-h-96 overflow-y-auto font-mono text-xs\">\n        <!-- Rendered dynamically -->\n      </div>\n    </div>\n\n    \n    <!-- SEO & Capabilities Section -->\n    <div class=\"mt-8 sm:mt-12 pt-6 sm:pt-8 border-t border-[#1e2333] grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8\">\n      <div>\n        <h2 class=\"text-sm sm:text-base font-bold mb-2 sm:mb-2.5\">Über UUID v4 Online Generator</h2>\n        <p class=\"text-xs opacity-75 leading-relaxed\">\n          Online-Tool mit Null-Latenz für <strong>uuid generator online</strong>. Alle Operationen laufen lokal in der Sandbox Ihres Browsers ohne Serverübertragung.\n        </p>\n        <h3 class=\"text-xs font-bold uppercase tracking-wider opacity-70 mt-3 sm:mt-4 mb-2\">Unterstützte Suchanfragen & Funktionen</h3>\n        <ul class=\"space-y-0.5\"><li class='flex items-center text-xs opacity-75 py-1 font-mono'><span class='mr-2' style='color:#10b981'>+</span>guid erstellen</li><li class='flex items-center text-xs opacity-75 py-1 font-mono'><span class='mr-2' style='color:#10b981'>+</span>uuid v4 massenhaft</li></ul>\n      </div>\n      <div>\n        <h2 class=\"text-sm sm:text-base font-bold mb-2 sm:mb-2.5\">Architektur & Datenschutzgarantie</h2>\n        <div class=\"space-y-2\">\n          <div class=\"p-3 sm:p-3.5 rounded-xl border border-[#1e2333] hover:border-[#10b981]/50 bg-black/5 dark:bg-white/5\">\n            <div class=\"text-xs font-bold\">100% Client-seitige Datenverarbeitung</div>\n            <p class=\"text-[11px] opacity-60 mt-0.5\">Ihre sensiblen Daten verlassen niemals Ihr Gerät. Keine Serverprotokolle oder Analysen.</p>\n          </div>\n          <div class=\"p-3 sm:p-3.5 rounded-xl border border-[#1e2333] hover:border-[#10b981]/50 bg-black/5 dark:bg-white/5\">\n            <div class=\"text-xs font-bold\">Edge-beschleunigt & Offline-bereit</div>\n            <p class=\"text-[11px] opacity-60 mt-0.5\">Nativ über moderne Web-APIs für sofortige Reaktionszeiten unter 1 ms ausgeführt.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n        \n  </div>\n</div>\n\n<script>\n(function() {\n  let qty = 1;\n  const listEl = document.getElementById('uuid-list');\n  const btnGen = document.getElementById('btn-generate');\n  const btnCopyAll = document.getElementById('btn-copy-all');\n  const chkHyphens = document.getElementById('chk-hyphens');\n  const chkUpper = document.getElementById('chk-upper');\n  const chkBraces = document.getElementById('chk-braces');\n\n  function generateUUID() {\n    let u = crypto.randomUUID ? crypto.randomUUID() : '10000000-1000-4000-8000-100000000000'.replace(/[018]/g, c =>\n      (c ^ crypto.getRandomValues(new Uint8Array(1))[0] & 15 >> c / 4).toString(16)\n    );\n\n    if (!chkHyphens.checked) u = u.replace(/-/g, '');\n    if (chkUpper.checked) u = u.toUpperCase();\n    if (chkBraces.checked) u = ' + u + ';\n    return u;\n  }\n\n  function renderBatch() {\n    const arr = [];\n    for (let i = 0; i < qty; i++) arr.push(generateUUID());\n    listEl.innerHTML = arr.map((val, idx) => {\n      return '<div class=\"p-2.5 rounded-xl border border-[#1e2333] hover:border-[#10b981]/50 bg-white/5 flex items-center justify-between gap-2\">' +\n        '<span class=\"opacity-40 text-[10px] w-6\">' + (idx + 1) + '.</span>' +\n        '<span class=\"font-bold flex-1 select-all truncate text-xs sm:text-sm\">' + val + '</span>' +\n        '<button class=\"btn-copy-one px-2.5 py-1 text-xs rounded border border-[#1e2333] hover:border-[#10b981]/50 hover:bg-white/10 transition\" data-val=\"' + val + '\">In Zwischenablage kopieren</button>' +\n        '</div>';\n    }).join('');\n\n    document.querySelectorAll('.btn-copy-one').forEach(b => {\n      b.addEventListener('click', () => {\n        const v = b.getAttribute('data-val');\n        navigator.clipboard.writeText(v).then(() => {\n          if (window.showToast) window.showToast('Kopiert: {v}...'.replace('{v}', v.substring(0, 14)));\n        });\n      });\n    });\n  }\n\n  document.querySelectorAll('.btn-qty').forEach(btn => {\n    btn.addEventListener('click', () => {\n      qty = parseInt(btn.getAttribute('data-val'), 10);\n      document.querySelectorAll('.btn-qty').forEach(b => {\n        b.className = 'btn-qty px-2.5 py-1 text-xs rounded border border-[#1e2333] hover:border-[#10b981]/50 font-mono ' +\n          (b === btn ? 'font-bold bg-white/15' : 'hover:bg-white/10');\n      });\n      renderBatch();\n    });\n  });\n\n  btnGen.addEventListener('click', () => {\n    renderBatch();\n    if (window.showToast) window.showToast('{n} UUID(s) generiert'.replace('{n}', qty));\n  });\n\n  [chkHyphens, chkUpper, chkBraces].forEach(el => el.addEventListener('change', renderBatch));\n\n  btnCopyAll.addEventListener('click', () => {\n    const all = Array.from(document.querySelectorAll('.btn-copy-one')).map(b => b.getAttribute('data-val')).join('\n');\n    if (!all) return;\n    navigator.clipboard.writeText(all).then(() => {\n      if (window.showToast) window.showToast('Alle {n} UUIDs in die Zwischenablage kopiert!'.replace('{n}', qty));\n    });\n  });\n\n  renderBatch();\n})();\n</script>\n        \n  </main>\n\n  <!-- Internal Linking Matrix -->\n  <section class=\"border-t border-[#1e2333] py-12 px-4 sm:px-6 lg:px-8 opacity-95\">\n    <div class=\"max-w-7xl mx-auto\">\n      <div class=\"flex items-center justify-between mb-6\">\n        <h3 class=\"text-sm font-bold uppercase tracking-wider opacity-80 font-mono\">\n          [+] Entwickler-Tools Verzeichnis\n        </h3>\n        <span class=\"text-xs opacity-60 font-mono\">7 Alle Werkzeuge</span>\n      </div>\n\n      <div class=\"grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3\">\n        \n        <a href=\"/de/json-formatter-validator\" class=\"p-3.5 rounded-lg border border-[#1e2333] hover:border-[#10b981]/50 bg-[#11141d] transition group block\">\n          <div class=\"text-xs font-bold truncate group-hover:underline\">\n            JSON Formatierer & Validator\n          </div>\n          <p class=\"text-[11px] opacity-60 mt-1 line-clamp-1\">\n            JSON-Dateien formatieren, validieren und bereinigen ohne Datenübertragung an Server.\n          </p>\n        </a>\n        \n        <a href=\"/de/base64-encoder-decoder\" class=\"p-3.5 rounded-lg border border-[#1e2333] hover:border-[#10b981]/50 bg-[#11141d] transition group block\">\n          <div class=\"text-xs font-bold truncate group-hover:underline\">\n            Base64 Kodierer & Dekodierer\n          </div>\n          <p class=\"text-[11px] opacity-60 mt-1 line-clamp-1\">\n            Text in Base64 umwandeln oder Base64-Zeichenketten sekundenschnell decodieren.\n          </p>\n        </a>\n        \n        <a href=\"/de/regex-tester-debugger\" class=\"p-3.5 rounded-lg border border-[#1e2333] hover:border-[#10b981]/50 bg-[#11141d] transition group block\">\n          <div class=\"text-xs font-bold truncate group-hover:underline\">\n            RegEx Tester & Debugger\n          </div>\n          <p class=\"text-[11px] opacity-60 mt-1 line-clamp-1\">\n            RegEx-Muster interaktiv testen und validieren mit sofortiger Hervorhebung.\n          </p>\n        </a>\n        \n        <a href=\"/de/jwt-token-decoder\" class=\"p-3.5 rounded-lg border border-[#1e2333] hover:border-[#10b981]/50 bg-[#11141d] transition group block\">\n          <div class=\"text-xs font-bold truncate group-hover:underline\">\n            JWT Token Dekodierer\n          </div>\n          <p class=\"text-[11px] opacity-60 mt-1 line-clamp-1\">\n            JWT Tokens einsehen, Header und Payload entschlüsseln ohne Server-Übertragung.\n          </p>\n        </a>\n        \n        <a href=\"/de/hash-generator-md5-sha256\" class=\"p-3.5 rounded-lg border border-[#1e2333] hover:border-[#10b981]/50 bg-[#11141d] transition group block\">\n          <div class=\"text-xs font-bold truncate group-hover:underline\">\n            Hash Generator (SHA/MD5)\n          </div>\n          <p class=\"text-[11px] opacity-60 mt-1 line-clamp-1\">\n            Kryptografische Prüfsummen berechnen mit SHA-256 und MD5.\n          </p>\n        </a>\n        \n        <a href=\"/de/unix-timestamp-epoch-converter\" class=\"p-3.5 rounded-lg border border-[#1e2333] hover:border-[#10b981]/50 bg-[#11141d] transition group block\">\n          <div class=\"text-xs font-bold truncate group-hover:underline\">\n            Unix Zeitstempel Konverter\n          </div>\n          <p class=\"text-[11px] opacity-60 mt-1 line-clamp-1\">\n            Unix Epoch Zeitstempel in lesbare Datumsformate umwandeln und umgekehrt.\n          </p>\n        </a>\n        \n        <a href=\"/de/uuid-guid-v4-generator\" class=\"p-3.5 rounded-lg border border-[#1e2333] hover:border-[#10b981]/50 bg-[#11141d] transition group block\">\n          <div class=\"text-xs font-bold truncate group-hover:underline\">\n            UUID v4 Online Generator\n          </div>\n          <p class=\"text-[11px] opacity-60 mt-1 line-clamp-1\">\n            Kryptografisch sichere UUID v4 Identifikatoren stapelweise generieren.\n          </p>\n        </a>\n        \n      </div>\n    </div>\n  </section>\n\n  <!-- Footer -->\n  <footer class=\"border-t border-[#1e2333] py-8 text-center text-xs opacity-75\">\n    <div class=\"max-w-7xl mx-auto px-4 flex flex-col md:flex-row items-center justify-between gap-4\">\n      <div>\n        &copy; 2026 <strong>DevZen Tools</strong>. Schnell, 100% lokal & Cloudflare Edge beschleunigt.\n      </div>\n      <div class=\"flex space-x-4 font-mono text-[11px]\">\n        <a href=\"/sitemap.xml\" class=\"hover:underline\">sitemap.xml</a>\n        <a href=\"/robots.txt\" class=\"hover:underline\">robots.txt</a>\n        <a href=\"https://globalcorehub.com\" target=\"_blank\" class=\"hover:underline\">globalcorehub</a>\n      </div>\n    </div>\n  </footer>\n\n  <script>\n  (function() {\n    // 0. Tools Dropdown Toggle\n    const toolsBtn = document.getElementById('tools-dropdown-btn');\n    const toolsPanel = document.getElementById('tools-dropdown-panel');\n    const toolsArrow = document.getElementById('tools-arrow-icon');\n    if (toolsBtn && toolsPanel) {\n      toolsBtn.addEventListener('click', (e) => {\n        e.stopPropagation();\n        const isHidden = toolsPanel.classList.toggle('hidden');\n        if (toolsArrow) toolsArrow.classList.toggle('rotate-180', !isHidden);\n      });\n      document.addEventListener('click', (e) => {\n        if (!toolsPanel.contains(e.target) && e.target !== toolsBtn) {\n          toolsPanel.classList.add('hidden');\n          if (toolsArrow) toolsArrow.classList.remove('rotate-180');\n        }\n      });\n    }\n\n    // 0.1 Quick Search Trigger Action\n    function triggerSearchFocus() {\n      const searchInput = document.getElementById('tool-search');\n      if (searchInput) {\n        searchInput.focus();\n        searchInput.scrollIntoView({ behavior: 'smooth', block: 'center' });\n      } else {\n        window.location.href = '/de/#tool-search';\n      }\n    }\n    const globalSearchBtn = document.getElementById('global-search-btn');\n    const mobileSearchBtn = document.getElementById('mobile-search-trigger');\n    if (globalSearchBtn) globalSearchBtn.addEventListener('click', triggerSearchFocus);\n    if (mobileSearchBtn) mobileSearchBtn.addEventListener('click', triggerSearchFocus);\n\n    if (window.location.hash === '#tool-search') {\n      setTimeout(() => {\n        const s = document.getElementById('tool-search');\n        if (s) { s.focus(); s.scrollIntoView({ behavior: 'smooth', block: 'center' }); }\n      }, 300);\n    }\n\n    // 1. Language dropdown menu\n    const langBtn = document.getElementById('lang-toggle-btn');\n    const langMenu = document.getElementById('lang-dropdown-menu');\n    if (langBtn && langMenu) {\n      langBtn.addEventListener('click', (e) => {\n        e.stopPropagation();\n        langMenu.classList.toggle('hidden');\n      });\n      document.addEventListener('click', () => {\n        if (!langMenu.classList.contains('hidden')) langMenu.classList.add('hidden');\n      });\n    }\n\n    // 2. Responsive Mobile Drawer Menu\n    const menuBtn = document.getElementById('mobile-menu-btn');\n    const mobileMenu = document.getElementById('mobile-menu');\n    const hamburgerIcon = document.getElementById('hamburger-icon');\n    const closeIcon = document.getElementById('close-icon');\n\n    if (menuBtn && mobileMenu) {\n      menuBtn.addEventListener('click', (e) => {\n        e.stopPropagation();\n        const isOpen = !mobileMenu.classList.contains('hidden');\n        if (isOpen) {\n          mobileMenu.classList.add('hidden');\n          if (hamburgerIcon) hamburgerIcon.classList.remove('hidden');\n          if (closeIcon) closeIcon.classList.add('hidden');\n        } else {\n          mobileMenu.classList.remove('hidden');\n          if (hamburgerIcon) hamburgerIcon.classList.add('hidden');\n          if (closeIcon) closeIcon.classList.remove('hidden');\n        }\n      });\n\n      document.addEventListener('click', (e) => {\n        if (!mobileMenu.contains(e.target) && e.target !== menuBtn) {\n          mobileMenu.classList.add('hidden');\n          if (hamburgerIcon) hamburgerIcon.classList.remove('hidden');\n          if (closeIcon) closeIcon.classList.add('hidden');\n        }\n      });\n    }\n  })();\n  </script>\n</body>\n</html>", "type": "text/html; charset=utf-8"}, "/de/uuid-guid-v4-generator.html": {"content": "<!DOCTYPE html>\n<html lang=\"de\" class=\"scroll-smooth\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>UUID v4 Online Generator | DevZen Tools</title>\n  <meta name=\"description\" content=\"Kryptografisch sichere UUID v4 Identifikatoren stapelweise generieren.\">\n  <link rel=\"canonical\" href=\"https://webutil.globalcorehub.com/de/uuid-guid-v4-generator\">\n\n  <!-- International SEO hreflang tags (7 Languages) -->\n  <link rel=\"alternate\" hreflang=\"x-default\" href=\"https://webutil.globalcorehub.com/uuid-guid-v4-generator\">\n  <link rel=\"alternate\" hreflang=\"en\" href=\"https://webutil.globalcorehub.com/uuid-guid-v4-generator\">\n  <link rel=\"alternate\" hreflang=\"zh-CN\" href=\"https://webutil.globalcorehub.com/zh/uuid-guid-v4-generator\">\n  <link rel=\"alternate\" hreflang=\"es\" href=\"https://webutil.globalcorehub.com/es/uuid-guid-v4-generator\">\n  <link rel=\"alternate\" hreflang=\"pt\" href=\"https://webutil.globalcorehub.com/pt/uuid-guid-v4-generator\">\n  <link rel=\"alternate\" hreflang=\"de\" href=\"https://webutil.globalcorehub.com/de/uuid-guid-v4-generator\">\n  <link rel=\"alternate\" hreflang=\"fr\" href=\"https://webutil.globalcorehub.com/fr/uuid-guid-v4-generator\">\n  <link rel=\"alternate\" hreflang=\"ja\" href=\"https://webutil.globalcorehub.com/ja/uuid-guid-v4-generator\">\n\n  <!-- Open Graph / Social -->\n  <meta property=\"og:type\" content=\"website\">\n  <meta property=\"og:url\" content=\"https://webutil.globalcorehub.com/de/uuid-guid-v4-generator\">\n  <meta property=\"og:title\" content=\"UUID v4 Online Generator | DevZen Tools\">\n  <meta property=\"og:description\" content=\"Kryptografisch sichere UUID v4 Identifikatoren stapelweise generieren.\">\n  <meta property=\"og:site_name\" content=\"DevZen Tools\">\n  <meta property=\"og:locale\" content=\"de\">\n\n  <!-- Theme Specific Typography -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link href=\"https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;700;800&family=Plus+Jakarta+Sans:wght@400;600;700&display=swap\" rel=\"stylesheet\">\n\n  <!-- Tailwind CSS Core -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          colors: {\n            brand: '#10b981'\n          }\n        }\n      }\n    }\n  </script>\n\n  <!-- Theme Specific Styles -->\n  <style>\n    body { font-family: 'JetBrains Mono', monospace; }\n    \n        pre, code, kbd { font-family: 'JetBrains Mono', monospace; }\n        ::-webkit-scrollbar { width: 6px; height: 6px; }\n        ::-webkit-scrollbar-track { background: #0c0e14; }\n        ::-webkit-scrollbar-thumb { background: #1e2333; border-radius: 3px; }\n        ::-webkit-scrollbar-thumb:hover { background: #10b981; }\n        .terminal-dot-red { background-color: #ff5f56; }\n        .terminal-dot-yellow { background-color: #ffbd2e; }\n        .terminal-dot-green { background-color: #27c93f; }\n        \n  </style>\n\n  <!-- Structured Data JSON-LD -->\n  <script type=\"application/ld+json\">\n  {\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"WebApplication\",\n    \"name\": \"UUID v4 Online Generator\",\n    \"url\": \"https://webutil.globalcorehub.com/de/uuid-guid-v4-generator\",\n    \"description\": \"Kryptografisch sichere UUID v4 Identifikatoren stapelweise generieren.\",\n    \"applicationCategory\": \"UtilitiesApplication\",\n    \"operatingSystem\": \"All\",\n    \"offers\": {\n      \"@type\": \"Offer\",\n      \"price\": \"0\",\n      \"priceCurrency\": \"USD\"\n    }\n  }\n  </script>\n\n  <!-- Tech Stack Scripts (Alpine.js / Canvas loop / Terminal runtime) -->\n  \n        <script>\n        // Terminal Keyboard Shortcut (Ctrl+K or /) & Toast Notification Runtime\n        window.showToast = function(msg) {\n            const toast = document.createElement('div');\n            toast.className = 'fixed bottom-6 right-6 z-50 bg-[#10b981] text-black font-mono text-xs px-4 py-2.5 rounded-lg shadow-2xl font-bold flex items-center space-x-2 animate-bounce';\n            toast.innerHTML = '<span>></span><span>' + msg + '</span>';\n            document.body.appendChild(toast);\n            setTimeout(() => toast.remove(), 2500);\n        };\n        </script>\n        \n</head>\n<body class=\"bg-[#0c0e14] text-[#e2e8f0] min-h-screen flex flex-col transition-colors duration-200\">\n\n  \n\n  <!-- Header Navigation (Responsive Desktop & Mobile) -->\n  <header class=\"sticky top-0 z-50 bg-[#11141d]/90 backdrop-blur-md border-b border-[#1e2333]\">\n    <div class=\"max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 h-16 flex items-center justify-between\">\n      \n      <!-- Brand & Terminal Indicator -->\n      <div class=\"flex items-center space-x-2 sm:space-x-3\">\n        \n        <div class=\"hidden sm:flex items-center space-x-1.5 mr-1 sm:mr-2\">\n          <span class=\"w-3 h-3 rounded-full terminal-dot-red inline-block\"></span>\n          <span class=\"w-3 h-3 rounded-full terminal-dot-yellow inline-block\"></span>\n          <span class=\"w-3 h-3 rounded-full terminal-dot-green inline-block\"></span>\n        </div>\n        \n\n        <a href=\"/de/\" class=\"flex items-center space-x-2.5 sm:space-x-3 group\">\n          <div class=\"w-8 h-8 sm:w-9 sm:h-9 rounded-lg flex items-center justify-center font-black text-base sm:text-lg bg-[#10b981] hover:bg-[#059669] text-black font-bold tracking-tight shadow-[0_0_15px_rgba(16,185,129,0.3)]\">\n            D\n          </div>\n          <span class=\"text-base sm:text-lg font-extrabold tracking-tight truncate max-w-[150px] sm:max-w-none\">\n            DevZen Tools\n          </span>\n        </a>\n      </div>\n\n      <!-- Desktop Navigation Links (Clean Dropdown Architecture) -->\n      <nav class=\"hidden md:flex items-center space-x-1 lg:space-x-2 text-xs lg:text-sm font-medium\">\n        <a href=\"/de/\" class=\"px-2.5 py-1.5 rounded-lg hover:bg-white/5 transition opacity-90 whitespace-nowrap\">Startseite</a>\n\n        <!-- \"All Tools\" Structured Dropdown Menu -->\n        <div class=\"relative inline-block text-left\" id=\"tools-dropdown-container\">\n          <button id=\"tools-dropdown-btn\" type=\"button\" class=\"inline-flex items-center space-x-1 px-2.5 py-1.5 rounded-lg hover:bg-white/10 transition opacity-80 hover:opacity-100 font-medium\">\n            <span>Alle Werkzeuge</span>\n            <svg id=\"tools-arrow-icon\" class=\"w-3.5 h-3.5 opacity-60 transition-transform duration-200\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n              <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19 9l-7 7-7-7\"></path>\n            </svg>\n          </button>\n\n          <!-- Dropdown Panel (Categorized & Compact) -->\n          <div id=\"tools-dropdown-panel\" class=\"hidden absolute left-0 mt-1.5 w-72 sm:w-80 rounded-2xl bg-[#11141d] border border-[#1e2333] hover:border-[#10b981]/50 shadow-[0_4px_20px_rgba(0,0,0,0.5)] shadow-2xl z-50 p-2 font-mono text-xs backdrop-blur-xl\">\n            <div class=\"flex items-center justify-between px-2.5 py-1 text-[10px] uppercase tracking-wider opacity-50 border-b border-[#1e2333] hover:border-[#10b981]/50/50 mb-1\">\n              <span>Entwickler-Tools Verzeichnis</span>\n              <span>7 Alle Werkzeuge</span>\n            </div>\n            <div class=\"max-h-72 overflow-y-auto space-y-0.5\">\n              \n              <a href=\"/de/j